// Ebenen bestimmen (17.10.2026): timeBuzzer liefert die Ebenen mit parent und child. Die oberste Ebene (ohne parent) ist Kunden,
// ihr child ist Projekte, dessen child ist Aufgaben. So braucht kein Ablauf feste Ebenen-Nummern.
const L = $input.all().map(i => i.json).filter(l => l && l.id !== undefined && l.id !== null);
const nachId = {};
for (const l of L) nachId[String(l.id)] = l;
const oben = L.filter(l => l.parent === null || l.parent === undefined || l.parent === '').sort((a, b) => (Number(a.index) || 0) - (Number(b.index) || 0));
const k = oben[0];
const p = k && k.child ? nachId[String(k.child)] : null;
const a = p && p.child ? nachId[String(p.child)] : null;
if (!k || !p || !a) throw new Error('timeBuzzer braucht drei Ebenen untereinander (Kunden, Projekte, Aufgaben). Gefunden: ' + (L.map(l => l.name).join(', ') || 'keine') + '. Abgleich abgebrochen, nichts geändert.');
return [{ json: { kunden: Number(k.id), projekte: Number(p.id), aufgaben: Number(a.id), namen: [k.name, p.name, a.name] } }];
